// src/pages/dashboard/components/StatsCards.js
import React from 'react';

const StatsCards = ({ stats, payments = [], users = [], courses = [] }) => {
  // Calculer les données dynamiques supplémentaires
  const calculateDynamicStats = () => {
    const currentDate = new Date();
    const currentMonth = currentDate.getMonth();
    const currentYear = currentDate.getFullYear();
    
    // Calculer les utilisateurs actifs ce mois-ci
    const activeUsersThisMonth = users.filter(user => {
      if (!user.lastLogin) return false;
      const lastLogin = new Date(user.lastLogin);
      return lastLogin.getMonth() === currentMonth && 
             lastLogin.getFullYear() === currentYear;
    }).length;

    // Calculer le nombre de formateurs uniques
    const uniqueInstructors = [...new Set(courses.map(course => course.instructor))].length;

    // Calculer le taux de croissance du mois
    const previousMonthRevenue = payments.reduce((sum, payment) => {
      if (payment.status === 'completed' && payment.paymentDate) {
        const paymentDate = new Date(payment.paymentDate);
        const prevMonth = currentMonth === 0 ? 11 : currentMonth - 1;
        const prevYear = currentMonth === 0 ? currentYear - 1 : currentYear;
        
        if (paymentDate.getMonth() === prevMonth && 
            paymentDate.getFullYear() === prevYear) {
          return sum + (payment.amount || 0);
        }
      }
      return sum;
    }, 0);

    const monthlyGrowthPercentage = previousMonthRevenue > 0 ? 
      ((stats.monthlyRevenue - previousMonthRevenue) / previousMonthRevenue * 100).toFixed(1) : 
      stats.monthlyRevenue > 0 ? 100 : 0;

    // Calculer la croissance des étudiants
    const previousMonthStudents = users.filter(user => {
      if (user.createdAt) {
        const createdAt = new Date(user.createdAt);
        const prevMonth = currentMonth === 0 ? 11 : currentMonth - 1;
        const prevYear = currentMonth === 0 ? currentYear - 1 : currentYear;
        return createdAt.getMonth() === prevMonth && 
               createdAt.getFullYear() === prevYear;
      }
      return false;
    }).length;

    const studentGrowthPercentage = previousMonthStudents > 0 ? 
      ((stats.totalStudents - previousMonthStudents) / previousMonthStudents * 100).toFixed(1) : 
      stats.totalStudents > 0 ? 100 : 0;

    // Calculer la croissance des cours
    const previousMonthCourses = courses.filter(course => {
      if (course.createdAt) {
        const createdAt = new Date(course.createdAt);
        const prevMonth = currentMonth === 0 ? 11 : currentMonth - 1;
        const prevYear = currentMonth === 0 ? currentYear - 1 : currentYear;
        return createdAt.getMonth() === prevMonth && 
               createdAt.getFullYear() === prevYear;
      }
      return false;
    }).length;

    const courseGrowthPercentage = previousMonthCourses > 0 ? 
      ((stats.totalCourses - previousMonthCourses) / previousMonthCourses * 100).toFixed(1) : 
      stats.totalCourses > 0 ? 100 : 0;

    // Calculer la croissance du taux de conversion
    const previousMonthConversion = 15; // Valeur par défaut, à calculer dynamiquement
    const conversionGrowthPercentage = previousMonthConversion > 0 ? 
      ((stats.conversionRate - previousMonthConversion) / previousMonthConversion * 100).toFixed(1) : 
      stats.conversionRate > 0 ? 100 : 0;

    return {
      activeUsersThisMonth,
      uniqueInstructors,
      monthlyGrowthPercentage,
      studentGrowthPercentage,
      courseGrowthPercentage,
      conversionGrowthPercentage
    };
  };

  const dynamicStats = calculateDynamicStats();

  // Fonction pour déterminer la couleur du trend
  const getTrendColor = (percentage) => {
    const value = parseFloat(percentage);
    if (value > 0) return 'positive';
    if (value < 0) return 'negative';
    return 'neutral';
  };

  // Fonction pour formater le pourcentage
  const formatPercentage = (percentage) => {
    const value = parseFloat(percentage);
    if (value > 0) return `+${value}%`;
    if (value < 0) return `${value}%`;
    return '0%';
  };

  // Vérifier si les données sont valides
  const isValidStat = (value) => {
    return value !== undefined && value !== null && !isNaN(value);
  };

  return (
    <div className="stats-grid">
      {/* Carte des revenus */}
      <div className="stat-card">
        <div className="stat-header">
          <div className="stat-icon revenue">💰</div>
          {isValidStat(dynamicStats.monthlyGrowthPercentage) && (
            <div className={`stat-trend ${getTrendColor(dynamicStats.monthlyGrowthPercentage)}`}>
              {formatPercentage(dynamicStats.monthlyGrowthPercentage)}
            </div>
          )}
        </div>
        <div className="stat-value">
          {isValidStat(stats.totalRevenue) ? 
            `${stats.totalRevenue.toLocaleString()} TND` : 
            '0 TND'
          }
        </div>
        <div className="stat-label">Revenus Totaux</div>
        <div className="stat-subtitle">
          {isValidStat(stats.monthlyRevenue) ? 
            `${stats.monthlyRevenue.toLocaleString()} TND ce mois` : 
            'Chargement...'
          }
        </div>
        
        {/* Barre de progression pour le mois */}
        {isValidStat(stats.totalRevenue) && stats.totalRevenue > 0 && (
          <div className="progress-bar">
            <div 
              className="progress-fill" 
              style={{ 
                width: `${Math.min(100, (stats.monthlyRevenue / stats.totalRevenue) * 100)}%`,
                backgroundColor: '#10b981'
              }}
            ></div>
          </div>
        )}
      </div>

      {/* Carte des étudiants */}
      <div className="stat-card">
        <div className="stat-header">
          <div className="stat-icon students">👥</div>
          {isValidStat(dynamicStats.studentGrowthPercentage) && (
            <div className={`stat-trend ${getTrendColor(dynamicStats.studentGrowthPercentage)}`}>
              {formatPercentage(dynamicStats.studentGrowthPercentage)}
            </div>
          )}
        </div>
        <div className="stat-value">
          {isValidStat(stats.totalStudents) ? stats.totalStudents.toLocaleString() : '0'}
        </div>
        <div className="stat-label">Étudiants Actifs</div>
        <div className="stat-subtitle">
          {isValidStat(dynamicStats.activeUsersThisMonth) ? 
            `${dynamicStats.activeUsersThisMonth} actifs ce mois` : 
            'Chargement...'
          }
        </div>
        
        {/* Indicateur d'activité */}
        {dynamicStats.activeUsersThisMonth > 0 && (
          <div className="activity-indicator">
            <div className="active-dots">
              {[...Array(Math.min(dynamicStats.activeUsersThisMonth, 5))].map((_, i) => (
                <span key={i} className="active-dot"></span>
              ))}
            </div>
            <span className="activity-text">
              {dynamicStats.activeUsersThisMonth} en ligne
            </span>
          </div>
        )}
      </div>

      {/* Carte des cours */}
      <div className="stat-card">
        <div className="stat-header">
          <div className="stat-icon courses">📚</div>
          {isValidStat(dynamicStats.courseGrowthPercentage) && (
            <div className={`stat-trend ${getTrendColor(dynamicStats.courseGrowthPercentage)}`}>
              {formatPercentage(dynamicStats.courseGrowthPercentage)}
            </div>
          )}
        </div>
        <div className="stat-value">
          {isValidStat(stats.totalCourses) ? stats.totalCourses : '0'}
        </div>
        <div className="stat-label">Cours Disponibles</div>
        <div className="stat-subtitle">
          {isValidStat(dynamicStats.uniqueInstructors) ? 
            `${dynamicStats.uniqueInstructors} formateurs` : 
            'Chargement...'
          }
        </div>
        
        {/* Distribution par catégorie */}
        {courses.length > 0 && (
          <div className="category-distribution">
            <div className="category-tags">
              {Array.from(new Set(courses.map(c => c.category))).slice(0, 3).map((category, i) => (
                <span key={i} className="category-tag">
                  {category}
                </span>
              ))}
              {Array.from(new Set(courses.map(c => c.category))).length > 3 && (
                <span className="category-tag more">
                  +{Array.from(new Set(courses.map(c => c.category))).length - 3}
                </span>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Carte du taux de conversion */}
      <div className="stat-card">
        <div className="stat-header">
          <div className="stat-icon conversion">📈</div>
          {isValidStat(dynamicStats.conversionGrowthPercentage) && (
            <div className={`stat-trend ${getTrendColor(dynamicStats.conversionGrowthPercentage)}`}>
              {formatPercentage(dynamicStats.conversionGrowthPercentage)}
            </div>
          )}
        </div>
        <div className="stat-value">
          {isValidStat(stats.conversionRate) ? 
            `${parseFloat(stats.conversionRate).toFixed(1)}%` : 
            '0%'
          }
        </div>
        <div className="stat-label">Taux de Conversion</div>
        <div className="stat-subtitle">
          {isValidStat(stats.totalPayments) ? 
            `${stats.totalPayments} paiements réussis` : 
            'Aucun paiement'
          }
        </div>
        
        {/* Indicateur de performance */}
        {isValidStat(stats.conversionRate) && (
          <div className="performance-indicator">
            <div className="performance-bar">
              <div 
                className="performance-fill" 
                style={{ 
                  width: `${Math.min(100, parseFloat(stats.conversionRate))}%`,
                  backgroundColor: parseFloat(stats.conversionRate) > 20 ? 
                    '#10b981' : parseFloat(stats.conversionRate) > 10 ? 
                    '#f59e0b' : '#ef4444'
                }}
              ></div>
            </div>
            <span className="performance-text">
              {parseFloat(stats.conversionRate) > 20 ? 'Excellent' : 
               parseFloat(stats.conversionRate) > 10 ? 'Bon' : 
               'À améliorer'}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default StatsCards;
